import{z as l,x as A,o as t,c as p,q as E,j as r,D as e,d as i,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"过拟合次数与试错","description":"","frontmatter":{"title":"过拟合次数与试错","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/backtest-overfitting.md","filePath":"quant/backtest-overfitting.md","lastUpdated":1791063341000}'),h={name:"quant/backtest-overfitting.md"};function B(d,a,m,c,f,_){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="过拟合次数与试错" tabindex="-1">过拟合次数与试错 <a class="header-anchor" href="#过拟合次数与试错" aria-label="Permalink to &quot;过拟合次数与试错&quot;">​</a></h1><div class="epigraph"><p>在同一段历史上对一簇规则取最优，检验统计量的原假设不再是「这一个规则没有技能」，而是「整簇规则里最好的那一个仍没有技能」；不把试错次数写进原假设，显著性就是搜出来的。</p><footer>—— White, A Reality Check for Data Snooping, Econometrica, 2000；Bailey, Borwein, López de Prado and Zhu, Notices of the AMS, 2014</footer></div><p><a href="/quant/probabilistic-sharpe">上一课</a>把 PSR 写成观测夏普超过预先声明阈值的渐近概率；\\(N=1\\) 时 DSR 退化为 PSR，有搜索时必须升级阈值。缺口是次数本身：参数网格、品种池、起止日期、成本假设都会把一次检验变成 \\(N\\) 次试错后再报告最大值。White 的 Reality Check 把最优绩效与「零技能簇的最大值」比较；Bailey 等人把同一机制写成试错足够多时任意回测目标都可以被拟合。本课写如何计数、如何进入极值，以及与 DSR、PBO、CPCV 的分工。不重推 PSR 的非正态标准误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设有 \\(N\\) 个候选规则，第 \\(n\\) 个在样本上的绩效统计量为 \\(f_n\\)（夏普、平均收益、相对基准的 \\(t\\)）。报告的是 \\(f^\\star=\\max_n f_n\\)。若每个 \\(f_n\\) 在无技能下均值接近零、且近似独立，则 \\(f^\\star\\) 的期望随 \\(N\\) 上升：正态情形大约是 \\(\\sigma\\sqrt{2\\log N}\\) 量级。把 \\(f^\\star\\) 送进「单次试验」的 \\(t\\) 检验，拒绝概率远高于名义水平。这就是数据窥探（data snooping）：不是算错了夏普，而是用错了原假设。</p><p><span class="marginnote">数字实例：按 \\(\\sigma\\sqrt{2\\ln N}\\) 算，无技能下最大值的期望外移是：\\(N=1\\) 时约 0，\\(N=100\\) 时约 \\(3.0\\sigma\\)，\\(N=10000\\) 时约 \\(4.3\\sigma\\)。也就是说，对一万条规则各回测一次，纯靠运气也能在样本内「发现」高出基准四个标准差的夏普——这不是谁作弊，是取最大值的数学必然。</span></p><p>White 针对的问题是：是否存在某个规则，其相对基准的期望绩效严格为正。朴素做法是看最优规则的 \\(t\\)；正确做法是看 \\(\\max_n\\sqrt{T}\\,\\bar d_n\\) 在「整簇均值差为零」下的分布，其中 \\(\\bar d_n\\) 是规则 \\(n\\) 相对基准的平均超额。Bailey 等人把同一最大值机制从「检验」推进到「设计」：若研究流程以样本内目标为停机条件，则停机时的回测几乎必然好看，样本外条件期望却在恶化。次数既是推断的参数，也是生产流程的状态变量。</p><h3 id="名义网格不是有效试验次数" tabindex="-1">名义网格不是有效试验次数 <a class="header-anchor" href="#名义网格不是有效试验次数" aria-label="Permalink to &quot;名义网格不是有效试验次数&quot;">​</a></h3><p>\\(N\\) 不能直接等于参数点的个数。完全相关的两个网格点（只把止损从 1.9% 改到 2.0%）不应计两次；几乎独立的信号家族（动量与事件驱动）应分开累加。有效试验次数 \\(N_{\\mathrm{eff}}\\) 介于 \\(1\\) 与名义格子数之间，取决于绩效序列的相关结构。漏计与过计方向相反：漏计让 Reality Check 与 DSR 假显著；把不相关市场、不相关年份的失败全部塞进 \\(N\\)，会过罚一个预注册策略。纪律是预先划定搜索空间，按空间的有效维度计 \\(N\\)，空间外的灵感要么新注册一次试验，要么承认 \\(N\\) 增加。</p><p><span class="marginnote">Git 里被丢掉的分支、看过结果再改的成本假设、换一段「更有代表性」的样本，都是试验。论文脚注里的 \\(N\\) 几乎总是下界。没有搜索日志，任何对次数的修正都只覆盖公开的那一部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>White Reality Check。</strong> 对每个规则计算相对基准的绩效差序列，取样本均值向量 \\(\\bar{\\mathbf{d}}\\)。统计量为 \\(V=\\max_n\\sqrt{T}\\,\\bar d_n\\)（或再学生化）。用平稳自举（block bootstrap）在「中心化后的」差序列上重抽样，得到无技能下 \\(V^\\ast\\) 的分布，再看 \\(V\\) 的 \\(p\\) 值。中心化是为了在原假设下把均值拨回零，避免基准本身有漂移时自举失真。Reality Check 的原假设是<strong>所有规则都不优于基准</strong>；拒绝只说明簇里至少有一个有技能，并不自动给冠军发护照——多重优于仍要逐步法（Romano–Wolf）或 Hansen 的 SPA。</p><p><span class="marginnote">术语翻译：「平稳自举」是把时间序列切成许多带重叠的小段、再像洗牌一样重新拼装出「另一个平行历史」的方法。好处是拼出来的新样本自动保留了原来的自相关与波动聚集，比假设各期独立的普通自举更贴近金融数据；它扮演的角色，是在「无技能世界」里反复重演这场比赛，看冠军分数的正常上限在哪里。</span></p><p><strong>Hansen SPA。</strong> Super Reality Check / Superior Predictive Ability 对学生化最大值更敏感，并对「很差的备择」降权，减轻 Reality Check 因一堆明显无用规则而功效下降的问题。工程上：先丢掉经济上不可交易的规则，再做 SPA，而不是把垃圾规则留在簇里指望检验自己会忽略它们。</p><p><strong>把 \\(N\\) 写成回测元数据。</strong> 每一次研究运行记录：候选集合描述、名义 \\(N\\)、\\(N_{\\mathrm{eff}}\\) 的估计（例如绩效相关矩阵的特征值截断）、是否看过样本外再回头。Bailey–López de Prado 的 DSR 用极值近似把 \\(N\\) 与试验间夏普离散度折成阈值 \\(\\mathrm{SR}_0\\)；Reality Check 用自举直接读最大值分布。两者应同时存在：解析近似写进每一张表的脚注，自举在策略准入时跑一遍。</p><h3 id="试错停机与「看起来像样本外」" tabindex="-1">试错停机与「看起来像样本外」 <a class="header-anchor" href="#试错停机与「看起来像样本外」" aria-label="Permalink to &quot;试错停机与「看起来像样本外」&quot;">​</a></h3><p>若流程是「直到夏普超过 2 才停止搜索」，停机时的样本内统计量是可选停时的值，分布比固定 \\(N\\) 的最大值更偏。这时名义 \\(N\\) 还要加上停机规则带来的额外选择。把样本切成研究段与「样本外」，若样本外被用来在模型和窗口之间选择，见 <a href="/quant/walk-forward">滚动检验</a>，它仍是试验。真正的一次试验是：搜索空间、停机规则、验证段在看见任何结果之前锁定。</p><p><span class="marginnote">White 的 \\(p\\) 值低，只拒绝「整簇都无技能」。把冠军的点估计原样拿去算 <a href="/quant/kelly-sizing">Kelly</a> 或风险预算，等于把检验的存在性命题偷换成幅度命题。幅度仍受选择偏差膨胀，应使用紧缩夏普或样本外中位数，而不是 \\(f^\\star\\)。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>试错抬高的是 \\(\\mathbb{E}[\\max_n f_n]\\)，不抬高任何一个规则的真实均值。机制是极值：独立同分布的中心化统计量，最大值的位置按 \\(\\sqrt{\\log N}\\) 外移；弱相关时有效 \\(N\\) 变小，外移变慢，但不会消失。过拟合作为风险的实现路径是：用被抬高的 \\(f^\\star\\) 估计 \\(\\mu\\)，用样本内 \\(\\sigma\\) 配杠杆，实盘均值接近零时回撤被杠杆放大。它在账上像市场风险超限，根因是准入用了错误的原假设。</p>',20)),(t(),r(s,null,{default:e(()=>[o(n,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUP%5B%22%E8%AF%95%E9%94%99%E6%AC%A1%E6%95%B0%20N%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20MAX%5B%22%E6%9E%81%E5%80%BC%E5%A4%96%E7%A7%BB%3A%20%E6%A0%B7%E6%9C%AC%E5%86%85%E5%A4%8F%E6%99%AE%E8%99%9A%E9%AB%98%22%5D%0A%20%20MAX%20--%3E%20LEV%5B%22%E7%94%A8%E8%99%9A%E9%AB%98%20%CE%BC%20%E4%B8%8E%E6%A0%B7%E6%9C%AC%E5%86%85%20%CF%83%20%E9%85%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%E7%9C%9F%E5%AE%9E%E5%9D%87%E5%80%BC%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20LIVE%20--%3E%20DD%5B%22%E5%9B%9E%E6%92%A4%E8%A2%AB%E6%9D%A0%E6%9D%86%E6%94%BE%E5%A4%A7%22%5D%0A%20%20DD%20--%3E%20FACE%5B%22%E8%B4%A6%E9%9D%A2%E8%A1%A8%E7%8E%B0%E4%B8%BA%E9%A3%8E%E9%99%A9%E8%B6%85%E9%99%90%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20FACE%20--%3E%20ROOT%5B%22%E6%A0%B9%E5%9B%A0%3A%20%E5%87%86%E5%85%A5%E6%97%B6%E7%94%A8%E9%94%99%E5%8E%9F%E5%81%87%E8%AE%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">直觉类比：在全年级选「跑得最快的人」，只测一名同学，成绩大致代表他；测遍全年级再只报第一名，第一名的成绩里混着不少当天的运气。年级越大（\\(N\\) 越大），第一名越快——但换一天重赛，名次多半要掉。回测冠军就是全年级第一名：样本外重赛，才是他真实的水平。</span></p><p>与 PBO 的差别在于问题陈述。PBO 问：样本内冠军在对称划分的样本外是否系统性地掉到中位以下。Reality Check 问：最优者相对基准的均值差是否能用零技能簇的最大值解释。DSR 问：已经选出的那一个夏普，在非正态与 \\(N\\) 次试验下还有多少概率对应正技能。三次测量互补：RC/SPA 管推断，DSR 管单点夏普的脚注，PBO/CPCV 管冠军可迁移性。用其中任意一个替代另外两个，都会留下盲区——例如 SPA 拒绝后 PBO 仍可很高，若冠军只是在该样本的噪声上取胜。</p><h3 id="次数如何污染风险数字" tabindex="-1">次数如何污染风险数字 <a class="header-anchor" href="#次数如何污染风险数字" aria-label="Permalink to &quot;次数如何污染风险数字&quot;">​</a></h3><p><a href="/quant/var-methods">VaR</a> 与 <a href="/quant/expected-shortfall">ES</a> 若在同一段历史上被用来选择窗口、衰减因子、置信水平或「哪一种方法好看」，分位数本身也过拟合。历史 VaR 的窗口长度、FHS 的 GARCH 阶数、Copula 的族，都是 \\(N\\) 的一部分。风险模型的回测（Kupiec / Christoffersen）假定 \\(v_t\\) 是预先指定的；若 \\(v_t\\) 来自「在样本上挑通过率最高的设定」，通过率的名义水平失效。次数纪律必须从 alpha 研究延伸到风险参数：限额模型的超参数应预注册，或至少把选择次数记进模型卡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Reality Check 对基准敏感：基准选得极弱，很容易拒绝；基准选成已经过拟合的姐妹策略，又可能不拒绝。SPA 改善功效，但不消除隐藏试验。相关结构时变时，\\(N_{\\mathrm{eff}}\\) 本身是估计量，对它再做选择又是一层窥探。块自举的块长是带宽：太短破坏依赖，太长使有效重复不够。</p><p>不要用「我们做了样本外」替代报 \\(N\\)。不要把因子动物园的 \\(t\\gt 3\\)（Harvey–Liu–Zhu）直接当成交易系统的次数校准：策略配置的搜索空间往往更大，门槛应更高。也不要把失败试验从簇里删掉再跑 RC——那是在条件于「看起来不差」的子集上做检验。发表后衰减（McLean–Pontiff）提供第三种证据：统计量过关之后，仍要用从未参与选择的样本看绩效是否还在。</p><p><span class="marginnote">把过拟合次数当成操作风险事件（未记录搜索）还是模型风险（统计量未调整），会影响停机与资本。更干净的规则是：未申报 \\(N\\) 的策略，风险预算为零，而不是给一个「打过折的 alpha」继续交易。</span></p>',8)),(t(),r(s,null,{default:e(()=>[o(n,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20Space%5B%22%E9%A2%84%E5%85%88%E9%94%81%E5%AE%9A%E7%9A%84%E6%90%9C%E7%B4%A2%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20N%5B%22%E5%90%8D%E4%B9%89%20N%20%E4%B8%8E%E6%9C%89%E6%95%88%20N_eff%22%5D%0A%20%20Space%20--%3E%20Run%5B%22N%20%E6%AC%A1%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20Run%20--%3E%20Max%5B%22%E6%8A%A5%E5%91%8A%E6%9C%80%E5%A4%A7%E5%80%BC%20f_star%22%5D%0A%20%20N%20--%3E%20RC%5B%22White%20RC%20%2F%20Hansen%20SPA%22%5D%0A%20%20Max%20--%3E%20RC%0A%20%20N%20--%3E%20DSR%5B%22DSR%20%E9%98%88%E5%80%BC%20SR_0%22%5D%0A%20%20Max%20--%3E%20DSR%0A%20%20Run%20--%3E%20PBO%5B%22CPCV%20%E4%B8%8A%E7%9A%84%20PBO%22%5D%0A%20%20RC%20--%3E%20Gate%5B%22%E7%AD%96%E7%95%A5%E5%87%86%E5%85%A5%22%5D%0A%20%20DSR%20--%3E%20Gate%0A%20%20PBO%20--%3E%20Gate%0A%20%20Gate%20--%3E%20Risk%5B%22%E6%89%8D%E8%BF%9B%E5%85%A5%20VaR%20%2F%20%E6%9D%A0%E6%9D%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报告最大值时，原假设必须是「整簇无技能」，而不是「这一个规则无技能」。</li><li>White Reality Check 用自举读最优绩效差的最大值分布；Hansen SPA 对学生化最大值更有功效。</li><li>有效试验次数由绩效相关结构决定，名义网格、隐藏分支与停机规则都会改 \\(N\\)。</li><li>RC/SPA、DSR、PBO 分别管推断、单点夏普与冠军可迁移性，不能互相替代。</li><li>风险模型的窗口与方法若也被选择过，VaR 回测的名义水平同样失效。</li><li>出处：White, <em>Econometrica</em>, 2000；Hansen, <em>Journal of Business &amp; Economic Statistics</em>, 2005；Bailey, Borwein, López de Prado and Zhu, <em>Notices of the AMS</em>, 2014；Romano and Wolf 逐步多重检验；对照 Bailey and López de Prado, <em>Journal of Portfolio Management</em>, 2014。</li></ul>',2))])}const D=l(h,[["render",B]]);export{C as __pageData,D as default};
